  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询地区名称。",
            "sampleValue": "青浦区"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "24°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "大风"
          },
          "windDirection": {
            "type": "string",
            "description": "当前风向。",
            "sampleValue": "西北风"
          },
          "windLevel": {
            "type": "integer",
            "description": "当前风力等级。",
            "sampleValue": 7
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_earphone.png",
      "description": "耳机图标，适合用于表达蓝牙耳机已连接状态。"
    },
    {
      "src": "resources/base/media/tornado.png",
      "description": "龙卷风彩色天气图标，适合用于表达大风、强风或恶劣风况。"
    },
    {
      "src": "resources/base/media/music_fill.svg",
      "description": "音乐音符实心图标，适合用于音乐入口和歌单快捷功能。"
    },
    {
      "src": "resources/base/media/icon_music.png",
      "description": "音乐图标，适合用于戴耳机播控和歌单入口。"
    },
    {
      "src": "resources/base/media/bell_slash_fill.svg",
      "description": "铃铛加斜杠实心图标，适合用于静音模式、关闭通知或勿扰状态。"
    }
  ]
}

